import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Tunnel.
 *
 * @stability experimental
 */
export interface ITunnelRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Tunnel resource.
     */
    readonly tunnelRef: TunnelReference;
}
/**
 * A reference to a Tunnel resource.
 *
 * @struct
 * @stability external
 */
export interface TunnelReference {
    /**
     * The TunnelArn of the Tunnel resource.
     */
    readonly tunnelArn: string;
}
